STAGE_TITLES = [tr("Oson tayanch", "Простая опора", "Easy foundation"),
                tr("To‘ldirib borish", "Добавляем ноты", "Build the texture"),
                tr("Asl parcha", "Исходный фрагмент", "Original excerpt")]


def lesson_items():
    from .lesson_coaching import MOVEMENT, FINGERING
    items = []
    for number, lesson in enumerate(LESSONS):
        key = f"lesson:still:{lesson['code']}"
        stages = []
        for i, (selection, task) in enumerate(zip(lesson["selections"], lesson["tasks"])):
            stages.append({"id": f"{key}:stage:{i+1}", "title": STAGE_TITLES[i],
                           "instruction": task, "source_speed_percent": [60, 80, 100][i],
                           "_asset_key": key if i == 2 else f"{key}:stage:{i+1}",
                           "_generator": {"start": lesson["start"], "end": lesson["end"],
                                          "selection": selection, "speed_percent": [60,80,100][i]}})
        related = [lesson["related"]]
        if number + 1 < len(LESSONS):
            related.insert(0, f"lesson:still:{LESSONS[number+1]['code']}")
        items.append({"id": key, "kind": "lesson", "title": lesson["title"], "subtitle": lesson["intro"],
                      "intro": lesson["intro"], "category": lesson["category"], "level": None,
                      "goals": ["understanding", "musicality" if lesson["category"] == "expression" else "accuracy"],
                      "minutes": 12, "stages": stages, "ready_when": lesson["ready"],
                      "explanation": [
                          {"title": tr("Asosiy tushuncha", "Основная идея", "The idea"), "text": lesson["concept"]},
                          {"title": tr("Still ichida qanday eshitiladi?", "Как это звучит в Still?", "Hear it in Still"), "text": lesson["example"]},
                          {"title": tr("Nimaga quloq tutish kerak?", "На что обратить внимание?", "What to listen for"), "text": lesson["listening"]}],
                      "steps": [{"title": STAGE_TITLES[i], "instruction": task} for i, task in enumerate(lesson["tasks"])],
                      "source": {"start_seconds": lesson["start"], "end_seconds": lesson["end"],
                                 "transformation": tr("1–2: tanlangan notalar va sekinroq ijro. 3: ikkala qo‘lning asl notalari va vaqti.", "1–2: выбранные ноты и замедление. 3: исходные ноты и время обеих рук.", "1–2: selected notes at slower tempos. 3: original notes and timing for both hands.")},
                      "related_ids": related})
        items[-1]["explanation"].append({"title":tr("Qo‘l harakati", "Движение руки", "Hand movement"), "text":MOVEMENT[lesson["code"]]})
        if lesson["code"] in FINGERING:
            items[-1]["fingering"] = FINGERING[lesson["code"]]
        if number == 0:
            items[-1]["explanation"].insert(1, {
                "title": tr("Nota nomini klavishda topish", "Найти ноту на клавиатуре", "Find a named note on the keyboard"),
                "text": tr("Playerdagi harflar: C — do, D — re, E — mi, F — fa, G — sol, A — lya, B — si. C klavishi ikki qora klavish guruhining chapida. Raqam oktavani bildiradi: C4 — o‘rta do; C5 undan bir oktava yuqori. ♯ belgisi tovushni yarim tonga ko‘taradi: F♯ — F ning darhol o‘ngidagi klavish. Nota nomlarini yoqib, shu tayanchlarni pianinoda topib ko‘ring.",
                           "Буквы плеера: C — до, D — ре, E — ми, F — фа, G — соль, A — ля, B — си. C находится слева от группы из двух чёрных клавиш. Цифра обозначает октаву: C4 — среднее до, C5 на октаву выше. Знак ♯ повышает ноту на полутон: F♯ — клавиша сразу справа от F. Включите названия и найдите эти ориентиры на пианино.",
                           "The player uses C, D, E, F, G, A and B. C sits just left of each pair of black keys. The number names the octave: C4 is middle C; C5 is one octave higher. A sharp (♯) raises a pitch by one semitone: F♯ is the key immediately to the right of F. Enable note names and find these landmarks on your piano.")})
    return items
